-- CommandProject: first person, simulation side (generated by the launcher). Appended to the
-- game's own /lua/SimSync.lua; SimCallback 'CPFirstPerson' (SimCallbacks.lua) calls
-- CPFirstPersonSim with the units the player had selected. Only units of the army that sent the
-- command are used (OkayToMessWithArmy), so it is safe in multiplayer.
--   drive: F (forward -1..1) and S (sideways -1..1) along the camera direction DX, DZ
--   halt / stop: clears the orders and stops
--   fire: attacks the enemy unit Target (entity id) or the ground at Pos
function CPFirstPersonSim(data, units)
    if type(data) ~= 'table' then return end
    local list = {}
    for _, u in units or {} do
        local ok, mine = pcall(function() return (not u:IsDead()) and OkayToMessWithArmy(u:GetArmy()) end)
        if ok and mine then table.insert(list, u) end
    end
    if table.getn(list) == 0 then return end
    local cmd = data.Cmd
    if cmd == 'drive' then
        local f = math.max(-1, math.min(1, tonumber(data.F) or 0))
        local s = math.max(-1, math.min(1, tonumber(data.S) or 0))
        local dx, dz = tonumber(data.DX) or 0, tonumber(data.DZ) or 1
        local len = math.sqrt(dx * dx + dz * dz)
        if len < 0.001 then return end
        dx, dz = dx / len, dz / len
        -- right of the view direction on the ground (x to the right, z towards the bottom of the map)
        local rx, rz = -dz, dx
        local mx, mz = dx * f + rx * s, dz * f + rz * s
        local ml = math.sqrt(mx * mx + mz * mz)
        if ml < 0.001 then return end
        mx, mz = mx / ml, mz / ml
        local sx, sz = 1024, 1024
        pcall(function() sx, sz = GetMapSize() end)
        for _, u in list do
            local p = u:GetPosition()
            local speed = 5
            pcall(function()
                local phys = u:GetBlueprint().Physics
                speed = (phys and phys.MaxSpeed) or speed
            end)
            -- a target a little ahead: re-sent while the key is held, the unit keeps going
            local d = math.max(10, speed * 3)
            local x = math.max(2, math.min(sx - 2, p[1] + mx * d))
            local z = math.max(2, math.min(sz - 2, p[3] + mz * d))
            local y = p[2]
            pcall(function() y = GetSurfaceHeight(x, z) end)
            IssueClearCommands({ u })
            IssueMove({ u }, { x, y, z })
        end
    elseif cmd == 'halt' or cmd == 'stop' then
        IssueClearCommands(list)
        pcall(IssueStop, list)
    elseif cmd == 'fire' then
        if data.Target then
            local target = false
            pcall(function() target = GetEntityById(data.Target) end)
            if not target then pcall(function() target = GetUnitById(data.Target) end) end
            local enemy = false
            if target then
                pcall(function() enemy = (not target:IsDead()) and IsEnemy(list[1]:GetArmy(), target:GetArmy()) end)
            end
            if enemy then
                IssueClearCommands(list)
                IssueAttack(list, target)
            end
        elseif type(data.Pos) == 'table' then
            local x, z = tonumber(data.Pos[1]), tonumber(data.Pos[3])
            if x and z then
                local y = tonumber(data.Pos[2]) or 0
                pcall(function() y = GetSurfaceHeight(x, z) end)
                IssueClearCommands(list)
                IssueAttack(list, { x, y, z })
            end
        end
    end
end
